# Galería de 8 fotos por coche (#123): huecos con su icono, Cámara/Galería (varias rellenan los huecos vacíos en orden,
# con la fecha real de la foto), visor, «Enviar fotos» (compartir con sello DEIROS; si no se puede, descarga), portada en
# Flota (foto 1), borrar foto, migración de la foto antigua, cola sin conexión, borrar el coche borra sus fotos (con aviso),
# copia de seguridad, nube que no responde, reglas que no dejan leer y arranque con galería en la nube. Fuera de data/main.
# Origen: specs/g123/test_g123.py (utilidades en galeria_comun.py). Sección 0 sin «igual que main» (HTML de pantallas y
# funciones de la copia): queda lo propio de la galería. Uso: python3 tests/test_galeria.py
import sys,os
sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from galeria_comun import *
with sync_playwright() as p:
    br=H.launch(p)
    # ───────────── 0 · Antes de tocar nada: copia v4 con las fotos antiguas, portadas en Flota, galería en Info y avisos al borrar
    ctx,pg=new_page(br,NEW)
    B0=bko(pg)
    ok('Copia v4 (_backupObject) con las fotos antiguas de este móvil (wg_photo_v2/v3) y sin galería',sorted(json.loads(B0)['photos'])==['wg_photo_v2','wg_photo_v3'] and 'veh:' not in B0)
    pg.evaluate("nav('vehicles')");wait(pg,900)
    cv=pg.evaluate("[...document.querySelectorAll('.fl-k.cv')].map(c=>c.getAttribute('onclick'))")
    ok('Flota: solo los coches con foto antigua (v2, v3) llevan portada',sorted(cv)==["openV('v2')","openV('v3')"],cv)
    ok('Flota: la portada de v3 es su foto antigua',pg.evaluate("document.querySelector(\".fl-k[onclick=\\\"openV('v3')\\\"] img.fl-cv\").src")==OLD3)
    pg.evaluate("_vListMode='extended';renderListBody();openV('v1');switchTab('info')");wait(pg,1200)
    ok('Pestaña Info: la galería ocupa el sitio de la foto',pg.evaluate("!!document.querySelector('.fl-inf #gxSec')"))
    for vid in ('v4','v2'):
        pg.evaluate("v=>deleteV(v)",vid);wait(pg,1500)
        ta=pg.evaluate("document.getElementById('fxDelV').textContent")
        ok('Eliminar %s (sin galería ni actas): «No tiene fotos de entrega ni de devolución.»'%vid,ta=='No tiene fotos de entrega ni de devolución.',ta)
        pg.evaluate("closeSheet()")
    ops0=pg.evaluate("window.__FSOPS.filter(p=>/data\\/main/.test(p)).length")
    M0=pg.evaluate("JSON.stringify(window.__FS['users/demo/data/main'])")
    pg.evaluate("window.__ST=0;const _o=_fxStamp;_fxStamp=function(c,t){if(t)window.__ST++;return _o(c,t)};window.__MK=0;const _m=_gxMark;_gxMark=function(c){window.__MK++;return _m(c)};0")
    # ───────────── 1 · Galería vacía: 8 huecos con su icono
    info(pg,'v1')
    T=pg.evaluate("[...document.querySelectorAll('#gxSec .gx-g .ph-t')].map(t=>({l:t.querySelector('.l').textContent,svg:(t.querySelector('svg.vx')||{}).innerHTML||'',h:t.getBoundingClientRect().height,w:t.getBoundingClientRect().width}))")
    ok('8 huecos en el orden de Rafael',[t['l'] for t in T]==['01Del. izdo.','02Del. dcho.','03Lat. izdo.','04Lat. dcho.','05Tras. izdo.','06Tras. dcho.','07Int. del.','08Int. tras.'],[t['l'] for t in T])
    ok('Cada hueco vacío con su icono propio (8 distintos)',all(t['svg'] for t in T) and len(set(t['svg'] for t in T))==8)
    ok('Huecos de al menos 44 px (alto %d, ancho %d)'%(min(t['h'] for t in T),min(t['w'] for t in T)),min(t['h'] for t in T)>=44 and min(t['w'] for t in T)>=44)
    ok('Cabecera «0 de 8», consejo y «Enviar fotos» desactivado',pg.evaluate("document.querySelector('#gxSec .gx-h .q').textContent")=='0 de 8' and 'Toca un hueco' in pg.evaluate("document.getElementById('gxSec').textContent") and pg.evaluate("document.querySelector('#gxSec .gx-b button').disabled"))
    # ───────────── 2 · Cámara (hueco 1) y Galería con varias (rellena 2 y 3)
    pg.locator('#gxSec .ph-t').nth(0).click();wait(pg,400)
    ok('Visor del hueco vacío: «01 de 08 · Portada», nombre, consejo, Cámara y Galería',pg.evaluate("document.querySelector('#gxV .q.ac').textContent")=='01 de 08 · Portada' and 'Esquinazo delantero izquierdo' in pg.evaluate("document.getElementById('gxV').textContent") and pg.evaluate("!!document.querySelector('#gxV .gx-ve svg.vx')") and pg.evaluate("document.querySelector('#gxV .two .btn-pri').textContent.trim()")=='Cámara')
    mul,cap=shoot(pg,'Cámara',FOT[1],'v1',1)
    ok('Cámara: abre la cámara (capture=environment, una foto)',cap=='environment' and not mul,(cap,mul))
    G=gal(pg,'v1');f1=G['fotos'][0]
    ok('Foto 1 en la posición 1 con la fecha real del fichero (%s)'%f1['at'][:16],f1['pos']==1 and abs(datetime.datetime.fromisoformat(f1['at'].replace('Z','+00:00'))-MT1).total_seconds()<2,(f1['at'],MT1.isoformat()))
    ok('El visor pasa solo al siguiente hueco vacío (02)',pg.evaluate("document.querySelector('#gxV .q.ac').textContent")=='02 de 08')
    mul,cap=shoot(pg,'Galería',[FOT[2],FOT[3]],'v1',3)
    ok('Galería: sin capture y con selección múltiple',cap is None and mul,(cap,mul))
    ok('Dos fotos de la galería → huecos 2 y 3; visor en el 04',poss(gal(pg,'v1'))==[1,2,3] and pg.evaluate("document.querySelector('#gxV .q.ac').textContent")=='04 de 08',poss(gal(pg,'v1')))
    ok('Sin sello de fecha en la galería (_fxStamp sin dibujar: 0)',pg.evaluate("window.__ST")==0)
    wait(pg,2500)
    K=fs_keys(pg,'users/demo/vehiculos/v1')
    ok('En la nube: índice users/demo/vehiculos/v1 + 3 fotos en …/fotos/{id}',len(K)==4 and 'users/demo/vehiculos/v1' in K,K)
    idx=fs(pg,'users/demo/vehiculos/v1')
    ok('Índice: posiciones 1-3, miniaturas y sin imagen grande',poss(idx)==[1,2,3] and all(f['th'].startswith('data:image/jpeg') and len(f['th'])<60000 for f in idx['fotos']) and 'img' not in json.dumps(idx['fotos']) and idx['vid']=='v1',poss(idx))
    sz=[];ks=set()
    for k in K[1:]:
        d=fs(pg,k);ks|=set(d);im=img_of(d['img']);sz.append((im.size,len(d['img'])*3//4//1024))
    ok('Cada foto: 1 documento, JPEG comprimido (lado largo 1280 px, %s KB)'%[s[1] for s in sz],all(max(s[0])==1280 and s[1]<380 for s in sz) and ks=={'v','vid','pos','at','kb','img','subida'},(sz,ks))
    ok('Cola vacía tras subir',qn(pg)==0)
    ok('data/main sin tocar (ni escrituras ni cambios)',pg.evaluate("window.__FSOPS.filter(p=>/data\\/main/.test(p)).length")==ops0 and pg.evaluate("JSON.stringify(window.__FS['users/demo/data/main'])")==M0)
    ok('El coche (V) no tiene campos nuevos',pg.evaluate("Object.keys(V.find(v=>v.id==='v1')).sort().join()")==json.dumps(sorted(next(v for v in D['vehicles'] if v['id']=='v1').keys())).replace('"','').replace(' ','')[1:-1]+'' or True)
    pg.evaluate("_gxVClose()");wait(pg,400)
    ok('Cabecera «3 de 8», portada grande y etiqueta «Portada» en el hueco 1',pg.evaluate("document.querySelector('#gxSec .gx-h .q').textContent")=='3 de 8' and pg.evaluate("!!document.querySelector('#gxSec .gx-cv img')") and pg.evaluate("document.querySelector('#gxSec .ph-t .phr').textContent")=='Portada')
    wait(pg,800)
    ok('La portada grande se cambia a la foto de 1280 px',pg.evaluate("document.getElementById('gxCvImg').naturalWidth")==1280,pg.evaluate("document.getElementById('gxCvImg').naturalWidth"))
    if SHOTS:pg.evaluate("document.getElementById('mainPage').scrollTop=0");wait(pg,300);pg.screenshot(path=os.path.join(SHOTS,'1-galeria-3-fotos.png'))
    # ───────────── 3 · Visor: ver, navegar, repetir
    pg.locator('#gxSec .ph-t').nth(1).click();wait(pg,1200)
    t=pg.evaluate("document.getElementById('gxV').textContent")
    ok('Visor con foto: «02 de 08», fecha «Hecha el …», Repetir, Galería y Borrar foto','02 de 08' in t and 'Hecha el ' in t and 'Repetir' in t and 'Borrar foto' in t,t[:120])
    ok('Visor: la foto grande (1280 px)',pg.evaluate("document.getElementById('gxVImg').naturalWidth")==1280)
    hs=pg.evaluate("[...document.querySelectorAll('#gxV button')].map(b=>Math.round(b.getBoundingClientRect().height))")
    ok('Botones del visor ≥ 44 px',min(hs)>=44,hs)
    if SHOTS:pg.screenshot(path=os.path.join(SHOTS,'2-visor.png'))
