    ok('Repetir: en la nube, la vieja borrada y la nueva subida',fs(pg,'users/demo/vehiculos/v1/fotos/'+old2) is None and fs(pg,'users/demo/vehiculos/v1/fotos/'+n2) is not None and poss(fs(pg,'users/demo/vehiculos/v1'))==[1,2,3])
