    ok('Hoja «Enviar fotos»: 3 fotos marcadas y «Enviar 3 fotos»',pg.evaluate("document.querySelectorAll('#gxSG input:checked').length")==3 and not pg.evaluate("document.querySelector('#gxSB .btn-pri').disabled"))
    ok('Los ficheros se preparan al abrir, con el sello «DEIROS» (3)',pg.evaluate("window.__MK")==3)
    if SHOTS:pg.evaluate("document.getElementById('SH').scrollTop=0");wait(pg,300);pg.screenshot(path=os.path.join(SHOTS,'3-enviar-fotos.png'))
    pg.locator('#gxSG label').nth(1).click();wait(pg,200)
    ok('Quitar la 2: «Enviar 2 fotos» y «Marcar todas»',pg.evaluate("document.querySelector('#gxSB .btn-pri').textContent.trim()")=='Enviar 2 fotos' and 'Marcar todas' in pg.evaluate("document.getElementById('gxSB').textContent"))
