    sh=pg.evaluate("window.__SH[0]")
    ok('navigator.share en el mismo toque con 2 JPEG: %s'%sh['names'],sh['n']==2 and sh['names']==['Deiros-%s-01.jpg'%nm,'Deiros-%s-03.jpg'%nm] and sh['types']==['image/jpeg']*2 and sh['act'] is not False,sh and {k:sh[k] for k in ('names','act','title')})
    fi=img_of(sh['first'])
    ok('Foto enviada: 1280 px, %d KB'%(sh['sizes'][0]//1024),max(fi.size)==1280 and sh['sizes'][0]<600*1024)
    crop=fi.crop((fi.size[0]-260,fi.size[1]-70,fi.size[0],fi.size[1])).convert('L');ref=img_of(fs(pg,'users/demo/vehiculos/v1/fotos/'+gal(pg,'v1')['fotos'][0]['id'])['img']).crop((fi.size[0]-260,fi.size[1]-70,fi.size[0],fi.size[1])).convert('L')
    diff=ImageChops.difference(crop,ref).getextrema()[1]
    ok('Sello «DEIROS» abajo a la derecha (solo en lo enviado; la guardada va limpia)',diff>80,diff)
    if SHOTS:fi.crop((fi.size[0]-420,fi.size[1]-160,fi.size[0],fi.size[1])).save(os.path.join(TMP,'sello.png'))
    ok('Tras compartir se cierra la hoja',not pg.evaluate("document.getElementById('SH').classList.contains('open')"))
    # Sin menú de compartir: se descargan
    pg.evaluate("window.__CAN=false");dls=[]
    pg.on('download',lambda d:dls.append(d.suggested_filename))
    pg.locator('#gxSec .gx-b button',has_text='Enviar fotos').click()
    pg.wait_for_function("/Enviar 3 fotos/.test((document.querySelector('#gxSB .btn-pri')||{}).textContent||'')",timeout=20000)
    pg.locator('#gxSB .btn-pri').click();wait(pg,2500)
    ok('Si no se puede compartir: se descargan las 3 (%s)'%dls,len(dls)==3 and all(x.endswith('.jpg') for x in dls))
    pg.evaluate("window.__CAN=true;window.__ABORT=true;window.__SH=[]")
    pg.locator('#gxSec .gx-b button',has_text='Enviar fotos').click()
    pg.wait_for_function("/Enviar 3 fotos/.test((document.querySelector('#gxSB .btn-pri')||{}).textContent||'')",timeout=20000)
    n0=len(dls);pg.locator('#gxSB .btn-pri').click();wait(pg,1200)
    ok('Cancelar el menú de compartir: no descarga y la hoja sigue abierta',len(dls)==n0 and pg.evaluate("document.getElementById('SH').classList.contains('open')"))
