    ok('Borrar la 3: pregunta, queda vacía (icono) y se borra de la nube',pg.evaluate("window.__CF")==['¿Borrar esta foto?'] and poss(gal(pg,'v1'))==[1,2] and pg.evaluate("!!document.querySelector('#gxV .gx-ve')") and fs(pg,'users/demo/vehiculos/v1/fotos/'+f3) is None and poss(fs(pg,'users/demo/vehiculos/v1'))==[1,2])
    pg.evaluate("_gxVClose()")
